#!/usr/bin/env python3
'''Read-only, offline, deterministic stdlib model check for K-TOOLS-001.

No project imports, file access, network, credentials, or subprocesses.
Finite integer endpoints and half-integer offsets are model inputs.
Manifest booleans are assumptions, not evidence about a real collector.
'''

from fractions import Fraction
from itertools import product


def need(condition, message):
    if not condition:
        raise AssertionError(message)


def interval(value):
    if not isinstance(value, tuple) or len(value) != 2:
        raise ValueError('expected endpoint tuple')
    s, e = value
    if type(s) is not int or type(e) is not int or e < s:
        raise ValueError('invalid integer interval')
    return s, e


def merge(xs):
    checked = [interval(x) for x in xs]
    out = []
    for s, e in sorted(x for x in checked if x[0] < x[1]):
        if out and s <= out[-1][1]:
            out[-1][1] = max(e, out[-1][1])
        else:
            out.append([s, e])
    return [tuple(x) for x in out]


def union_length(xs):
    return sum(e - s for s, e in merge(xs))


def coverage(query, xs):
    q0, q1 = interval(query)
    if q0 == q1:
        return False
    cursor = q0
    for s, e in merge(xs):
        if e <= cursor:
            continue
        if s > cursor:
            return False
        cursor = max(cursor, e)
        if cursor >= q1:
            return True
    return False


def occupied_units(xs):
    result = set()
    for x in xs:
        s, e = interval(x)
        result.update(range(s, e))
    return result


def faulty_envelope(query, xs):
    q0, q1 = interval(query)
    return bool(xs) and min(s for s, e in xs) <= q0 and max(e for s, e in xs) >= q1


def shape(record):
    s, e = interval((record['start'], record['end']))
    form = record.get('form')
    if form == 'point':
        if s != e:
            raise ValueError('point needs one timestamp')
        return 'point', s, e
    if form != 'duration':
        raise ValueError('unknown geometry')
    if s == e:
        if record.get('zero_is_occurrence') is not True:
            raise ValueError('ambiguous zero-duration row')
        return 'point', s, e
    return 'span', s, e


def offset(value):
    lo, hi = interval(value)
    return lo, hi


def temporal(event, shifts, query):
    form, s, e = event
    lo, hi = offset(shifts)
    q0, q1 = interval(query)
    if q0 == q1:
        raise ValueError('empty temporal query')
    if form == 'point':
        possible = s + lo < q1 and s + hi >= q0
        certain = s + lo >= q0 and s + hi < q1
    elif form == 'span' and s < e:
        possible = s + lo < q1 and e + hi > q0
        certain = s + hi < q1 and e + lo > q0
    else:
        raise ValueError('invalid normalized event')
    return 'ALL' if certain else 'MAY' if possible else 'NONE'


def reference_temporal(event, shifts, query):
    '''Enumerate half-unit offsets and occupied half-unit cells.

    Integer input boundaries partition the continuous offset range at
    integers. Endpoints plus half-unit interior witnesses suffice for
    this finite input family, including strict half-open boundaries.
    '''
    form, s, e = event
    lo, hi = offset(shifts)
    q0, q1 = interval(query)
    window_cells = set(range(2 * q0, 2 * q1))
    answers = []
    for shift2 in range(2 * lo, 2 * hi + 1):
        if form == 'point':
            answers.append(2 * s + shift2 in window_cells)
        else:
            event_cells = set(range(2 * s + shift2, 2 * e + shift2))
            answers.append(bool(event_cells.intersection(window_cells)))
    if all(answers):
        return 'ALL'
    if any(answers):
        return 'MAY'
    return 'NONE'


GATES = (
    'supported', 'enabled', 'scope_complete', 'loss_free', 'table',
    'schema', 'query_complete', 'event_complete', 'finalized',
    'boundary_complete', 'clock_certified',
)


def manifest():
    result = {key: True for key in GATES}
    result.update(query=(0, 10), chunks=[(0, 5), (5, 10)])
    return result


def row(s, e, **changes):
    result = dict(kind='event', scope='dev0', physical_id='p0',
                  members=('R',), fields_ok=True, form='duration',
                  start=s, end=e, zero_is_occurrence=True, shifts=(0, 0))
    result.update(changes)
    return result


def audit(m, records):
    '''Core absence certificate for active-event semantics.

    Deliberately conservative: malformed potentially relevant rows
    retain blockers even when nominal timestamps look irrelevant.
    Identity-complete duplicate groups are resolved before presence.
    '''
    q0, q1 = interval(m['query'])
    if q0 == q1:
        return 'NO_QUERY', 'NOT_APPLICABLE', ('EMPTY_QUERY',)
    reasons = {key for key in GATES if m.get(key) is not True}
    try:
        if not coverage(m['query'], m['chunks']):
            reasons.add('WINDOW_GAP')
    except (KeyError, TypeError, ValueError):
        reasons.add('COVERAGE_INVALID')

    normalized = {}
    conflicts = set()
    for r in records:
        if not isinstance(r, dict):
            reasons.add('INVALID_ROW')
            continue
        kind, scope = r.get('kind'), r.get('scope')
        if isinstance(kind, str) and kind != 'event':
            continue
        if isinstance(scope, str) and scope != 'dev0':
            continue
        if kind != 'event' or scope != 'dev0':
            reasons.add('UNKNOWN_DOMAIN_OR_SCOPE')
            continue
        pid = r.get('physical_id')
        if r.get('fields_ok') is not True or not isinstance(pid, str) or not pid:
            reasons.add('INVALID_ROW')
            continue
        try:
            event = shape(r)
        except (KeyError, TypeError, ValueError):
            reasons.add('INVALID_GEOMETRY')
            continue
        members = r.get('members')
        if members is None:
            reasons.add('JOIN_UNKNOWN')
            continue
        if not isinstance(members, tuple) or any(not isinstance(x, str) or not x for x in members):
            reasons.add('INVALID_IDENTITY')
            continue
        try:
            shifts = offset(r.get('shifts'))
        except (TypeError, ValueError):
            reasons.add('TIME_UNKNOWN')
            continue
        if m.get('clock_certified') is not True:
            reasons.add('TIME_UNKNOWN')
            continue
        value = (event, shifts, members)
        if pid in normalized:
            old_record, old_value = normalized[pid]
            if old_record != r or old_value != value:
                conflicts.add(pid)
                reasons.add('DUPLICATE_CONFLICT')
        else:
            normalized[pid] = (r, value)

    present = False
    for pid, (raw, value) in normalized.items():
        if pid in conflicts:
            continue
        event, shifts, members = value
        membership = temporal(event, shifts, m['query'])
        if membership == 'NONE' or 'R' not in members:
            continue
        if membership == 'MAY':
            reasons.add('UNKNOWN_AT_BOUNDARY')
        else:
            present = True
    if present:
        return 'SUPPORTED', 'REFUTED', tuple(sorted(reasons))
    if reasons:
        return 'UNKNOWN', 'UNSUPPORTED', tuple(sorted(reasons))
    return 'UNKNOWN', 'SUPPORTED_UNDER_CERTIFICATE', ()


def faulty_drop_invalid(m, records):
    return audit(m, [r for r in records if r.get('fields_ok') and r.get('physical_id')])


def faulty_nominal_clock(m, records):
    return audit(m, [dict(r, shifts=(0, 0)) for r in records])


def faulty_drop_points(m, records):
    return audit(m, [r for r in records if r['start'] < r['end']])


def test_intervals():
    intervals = [(s, e) for s in range(6) for e in range(s, 6)]
    count = 0
    for left, right in product(intervals, repeat=2):
        xs = [left, right]
        units = occupied_units(xs)
        need(union_length(xs) == len(units), 'union disagrees with unit reference')
        expected = set(range(5)).issubset(units)
        need(coverage((0, 5), xs) == expected, 'coverage disagrees with unit reference')
        count += 1
    need(union_length([]) == 0, 'empty union')
    need(not coverage((0, 5), []), 'empty coverage')
    need(not coverage((5, 5), [(0, 10)]), 'empty query is not a certificate')
    need(coverage((0, 10), [(0, 5), (5, 10)]), 'adjacent coverage')
    gap = [(0, 5), (6, 10)]
    need(faulty_envelope((0, 10), gap), 'envelope mutant trigger')
    need(not coverage((0, 10), gap), 'gap negative control was not detected')
    overlapping = [(0, 10), (5, 15)]
    need(union_length(overlapping) == 15, 'fixed overlap union')
    need(sum(e - s for s, e in overlapping) == 20, 'fixed cumulative duration')
    need(union_length(overlapping) != 20, 'sum-as-union mutant was not detected')
    try:
        union_length([(6, 5)])
    except ValueError:
        pass
    else:
        raise AssertionError('negative original interval accepted')
    return count


def test_temporal():
    count = 0
    for q0 in range(-1, 2):
        for q1 in range(q0 + 1, 5):
            for s in range(-2, 6):
                for e in range(s, 6):
                    event = ('point' if s == e else 'span', s, e)
                    for lo in range(-2, 2):
                        for hi in range(lo, 3):
                            actual = temporal(event, (lo, hi), (q0, q1))
                            expected = reference_temporal(event, (lo, hi), (q0, q1))
                            need(actual == expected, 'time classification disagrees with offset enumeration')
                            count += 1
    fixed = [
        (('point', 0, 0), (0, 0), 'ALL'),
        (('point', 5, 5), (0, 0), 'ALL'),
        (('point', 10, 10), (0, 0), 'NONE'),
        (('point', 10, 10), (-1, 0), 'MAY'),
        (('span', 10, 11), (-2, 0), 'MAY'),
        (('span', -2, 0), (0, 0), 'NONE'),
    ]
    for event, shifts, expected in fixed:
        need(temporal(event, shifts, (0, 10)) == expected, 'fixed endpoint/offset case')
    return count


def test_audit():
    m = manifest()
    supported = 'SUPPORTED_UNDER_CERTIFICATE'
    count = 0

    def expect(records, absence, data=None, presence=None):
        nonlocal count
        result = audit(m if data is None else data, records)
        need(result[1] == absence, 'audit absence mismatch: %r' % (result,))
        if presence is not None:
            need(result[0] == presence, 'audit presence mismatch')
        count += 1
        return result

    expect([], supported)
    for gate in GATES:
        broken = manifest()
        broken[gate] = False
        expect([], 'UNSUPPORTED', broken)
        missing = manifest()
        del missing[gate]
        expect([], 'UNSUPPORTED', missing)
        faulty_repaired = dict(broken)
        faulty_repaired[gate] = True
        need(audit(faulty_repaired, [])[1] == supported, 'gate-removal mutant trigger')
        need(audit(broken, [])[1] != supported, 'gate-removal mutant undetected')

    gap = manifest()
    gap['chunks'] = [(0, 5), (6, 10)]
    expect([], 'UNSUPPORTED', gap)
    empty = manifest()
    empty['query'] = (5, 5)
    expect([], 'NOT_APPLICABLE', empty, 'NO_QUERY')

    for r in [row(0, 0, form='point'), row(5, 5, form='point'), row(5, 5), row(4, 9)]:
        expect([r], 'REFUTED', presence='SUPPORTED')
    expect([row(10, 10, form='point')], supported)
    expect([row(10, 11)], supported)
    expect([row(4, 9, members=('OTHER',))], supported)
    expect([row(4, 9, members=())], supported)
    expect([row(4, 9, kind='other')], supported)
    expect([row(4, 9, scope='other')], supported)

    invalid = row(4, 9, physical_id=None)
    bad_field = row(4, 9, fields_ok=False)
    unjoined = row(4, 9, members=None)
    shifted = row(10, 11, shifts=(-2, 0))
    unknown_clock = row(100, 101, shifts=None)
    ambiguous_zero = row(5, 5, zero_is_occurrence=False)
    bad_geometry = row(6, 5)
    for r in [invalid, bad_field, unjoined, shifted, unknown_clock, ambiguous_zero, bad_geometry]:
        expect([r], 'UNSUPPORTED')
    expect([row(10, 10, form='point', shifts=(-1, 0))], 'UNSUPPORTED')
    expect([row(10, 11, shifts=(-2, -2))], 'REFUTED', presence='SUPPORTED')
    expect([row(100, 101, physical_id=None)], 'UNSUPPORTED')

    duplicate = row(4, 9)
    expect([duplicate, dict(duplicate)], 'REFUTED', presence='SUPPORTED')
    conflict = row(20, 21)
    result = expect([duplicate, conflict], 'UNSUPPORTED')
    need('DUPLICATE_CONFLICT' in result[2], 'conflicting group not quarantined')
    distinct = row(6, 7, physical_id='p1')
    expect([duplicate, distinct], 'REFUTED', presence='SUPPORTED')

    need(faulty_drop_invalid(m, [invalid])[1] == supported, 'invalid-row mutant trigger')
    need(audit(m, [invalid])[1] != supported, 'invalid-row mutant not detected')
    need(faulty_drop_invalid(m, [bad_field])[1] == supported, 'bad-field mutant trigger')
    need(audit(m, [bad_field])[1] != supported, 'bad-field mutant not detected')
    need(faulty_nominal_clock(m, [shifted])[1] == supported, 'nominal-clock mutant trigger')
    need(audit(m, [shifted])[1] != supported, 'nominal-clock mutant not detected')
    point = row(5, 5, form='point')
    need(faulty_drop_points(m, [point])[1] == supported, 'point-deletion mutant trigger')
    need(audit(m, [point])[1] == 'REFUTED', 'point-deletion mutant not detected')
    need(union_length([(5, 5)]) == 0, 'zero record contributes busy time')
    need(audit(m, [row(5, 5)])[0] == 'SUPPORTED', 'zero busy time incorrectly implies absence')
    return count


def queue_scan(initial, schedule):
    if type(initial) is not int or initial < 0:
        raise ValueError('invalid initial occupancy')
    q = initial
    peak = initial
    arrival_total = drain_total = 0
    for arrivals, capacity in schedule:
        if type(arrivals) is not int or type(capacity) is not int or min(arrivals, capacity) < 0:
            raise ValueError('invalid queue input')
        arrival_total += arrivals
        q += arrivals
        peak = max(peak, q)
        drained = min(q, capacity)
        q -= drained
        drain_total += drained
        need(q == initial + arrival_total - drain_total, 'byte conservation violated')
        need(0 <= drain_total <= initial + arrival_total, 'draining nonexistent bytes')
    return peak, q


def reference_queue(initial, schedule):
    queue = [None] * initial
    peak = len(queue)
    for arrivals, capacity in schedule:
        for _ in range(arrivals):
            queue.append(None)
            peak = max(peak, len(queue))
        for _ in range(capacity):
            if queue:
                queue.pop(0)
    return peak, len(queue)


def test_buffer():
    count = 0
    choices = list(product(range(3), repeat=2))
    for initial in range(3):
        for schedule in product(choices, repeat=3):
            need(queue_scan(initial, schedule) == reference_queue(initial, schedule),
                 'cumulative queue disagrees with byte reference')
            count += 1
    schedule = [(9, 0), (0, 10)]
    peak, final = queue_scan(2, schedule)
    need((peak, final) == (11, 1), 'hand-computable peak case')
    faulty_endpoint_safe = final <= 10
    correct_safe = peak <= 10
    need(faulty_endpoint_safe and not correct_safe, 'endpoint-only mutant not detected')
    need(peak <= 11, 'capacity 11 should cover this trajectory')
    need(queue_scan(0, [(0, 100), (9, 0)]) == (9, 9),
         'unused service was incorrectly banked')
    need(queue_scan(2, [(9, 10)])[0] == 11, 'same-time arrival peak was hidden')

    fluid_count = 0
    for a in range(4):
        for d in range(4):
            for initial in range(4):
                for rates in product(range(a + 1), repeat=3):
                    q = Fraction(initial)
                    peak = q
                    for rate in rates:
                        q = max(Fraction(0), q + rate - d)
                        peak = max(peak, q)
                    bound = initial + max(0, a - d) * len(rates)
                    need(peak <= bound, 'no-burst fluid rate bound violated')
                    fluid_count += 1
    initial, a, d, horizon, capacity = 11, 0, 10, 2, 10
    faulty_signed_endpoint = initial + (a - d) * horizon <= capacity
    corrected_peak_bound = initial + max(0, a - d) * horizon <= capacity
    need(faulty_signed_endpoint and not corrected_peak_bound,
         'initial-occupancy mutant not detected')
    return count, fluid_count


def test_shared():
    physical = [(4, 9)]
    logical_waits = [(4, 9), (4, 9)]
    need(union_length(physical) == 5, 'physical work duration')
    need(sum(e - s for s, e in logical_waits) == 10, 'logical wait sum')
    need(union_length(physical) != 10, 'logical-to-physical double charge undetected')
    weights = (Fraction(1, 2), Fraction(1, 2))
    need(sum(weights) == 1 and sum(5 * w for w in weights) == 5,
         'resource charge conservation')
    return 1


def main():
    counts = {}
    counts['interval_reference_cases'] = test_intervals()
    counts['temporal_reference_cases'] = test_temporal()
    counts['certificate_cases'] = test_audit()
    counts['byte_queue_cases'], counts['fluid_rate_cases'] = test_buffer()
    counts['shared_work_cases'] = test_shared()
    for name in sorted(counts):
        print(name + '=' + str(counts[name]))
    print('negative_controls=coverage-envelope,sum-as-union,omitted-gate,point-deletion,invalid-row-deletion,nominal-clock,duplicate-conflict,buffer-endpoint,initial-occupancy,logical-double-charge')
    print('PASS: finite event, certificate, interval and buffer models agree with scoped references/invariants')
    print('scope=CPU arithmetic only; manifest assumptions are not collector evidence; no GPU, profiler, I/O, RDMA or service measurements')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
